#!/usr/bin/env bash
# Print what a few public healthcare data sources offer, from a GitHub runner (open network).
set +e
echo "== CodiEsp (Zenodo)"; curl -s -m 60 "https://zenodo.org/api/records/3837305" | python3 -c "import json,sys; d=json.load(sys.stdin); print(d.get('metadata',{}).get('title'), d.get('metadata',{}).get('license')); [print(f['key'], f['size'], f['links']['self']) for f in d.get('files',[])]"
echo "== Zenodo search codiesp"; curl -s -m 60 "https://zenodo.org/api/records?q=codiesp&size=5" | python3 -c "import json,sys; d=json.load(sys.stdin); [print(h['id'], h['metadata']['title'], h['metadata'].get('version'), [f['key'] for f in h.get('files',[])]) for h in d['hits']['hits']]"
echo "== HF mtsamples"; curl -s -m 60 "https://huggingface.co/api/datasets?search=mtsamples&limit=10" | python3 -c "import json,sys; [print(d['id'], d.get('downloads')) for d in json.load(sys.stdin)]"
echo "== HF medical transcription"; curl -s -m 60 "https://huggingface.co/api/datasets?search=medical_transcription&limit=10" | python3 -c "import json,sys; [print(d['id'], d.get('downloads')) for d in json.load(sys.stdin)]"
echo "== HF medqa"; curl -s -m 60 "https://huggingface.co/api/datasets?search=medqa&limit=10&sort=downloads" | python3 -c "import json,sys; [print(d['id'], d.get('downloads')) for d in json.load(sys.stdin)]"
echo "== CMS"; for u in https://data.cms.gov/data.json https://www.cms.gov/medicare-coverage-database/downloads/downloads.aspx https://downloads.cms.gov/medicare-coverage-database/downloads/exports/ncd.zip https://downloads.cms.gov/medicare-coverage-database/downloads/exports/current_lcd.zip https://download.cms.gov/marketplace-puf/2024/transparency-in-coverage-puf.zip; do echo "$u $(curl -s -L -o /dev/null -w '%{http_code} %{size_download}' -m 120 $u)"; done
echo "== CMS TiC search"; curl -s -m 60 "https://data.cms.gov/data.json" | python3 -c "import json,sys; d=json.load(sys.stdin); [print(x['title']) for x in d['dataset'] if any(k in x['title'].lower() for k in ['denial','prior auth','appeal','transparency'])]" | head -20
